const $=id=>document.getElementById(id);
const N=v=>Number(String(v??"").replace(",","."))||0;
const F=v=>{const n=Number(v);return Number.isFinite(n)?String(n).replace(".",","):"0"};
const D2=v=>{const n=Number(v);return Number.isFinite(n)?n.toLocaleString("pl-PL",{minimumFractionDigits:2,maximumFractionDigits:2}):"0,00"};
const G=v=>Math.round(N(v)).toLocaleString("pl-PL");
const norm=v=>String(v||"").toLowerCase().normalize("NFD").replace(/[\u0300-\u036f]/g,"").trim();
let products=[],meals=[],ingredients=[],journal=[],entries=[],goals=[],dietPlans=[],planUsersRows=[],planEntries=[],planPortions=[],shoppingPrices=[];
let temp=[],chosenIng=null,editMeal=null,editProductId=null,jType="product",jChosen=null,jSlot="",editJournalId=null,jReturnContext=null;

async function loadAll(){
 const [p,m,s,d,e,g,pl,pu,pe,pp,sp]=await Promise.all([
  supabaseClient.from("produkty").select("*").order("nazwa"),
  supabaseClient.from("posilki").select("*").order("nazwa"),
  supabaseClient.from("skladniki_posilkow").select("*"),
  supabaseClient.from("dziennik").select("*"),
  supabaseClient.from("pozycje_dziennika").select("*"),
  supabaseClient.from("cele").select("*"),
  supabaseClient.from("plan_diety").select("*"),
  supabaseClient.from("plan_uczestnicy").select("*"),
  supabaseClient.from("pozycje_planu").select("*"),
  supabaseClient.from("porcje_planu").select("*"),
  supabaseClient.from("ceny_zakupow").select("*")
 ]);
 for(const r of[p,m,s,d,e,g,pl,pu,pe,pp,sp])if(r.error)throw r.error;
 products=p.data||[];meals=m.data||[];ingredients=s.data||[];journal=d.data||[];entries=e.data||[];goals=g.data||[];dietPlans=pl.data||[];planUsersRows=pu.data||[];planEntries=pe.data||[];planPortions=pp.data||[];shoppingPrices=sp.data||[];
 renderProducts();renderMeals();renderGoals();renderJournal();renderPlan();renderShopping();
}
function screen(id){["start","produkty","posilki","cele","plan","zakupy","dziennik"].forEach(x=>$(x).classList.add("hide"));$(id).classList.remove("hide");if(id==="dziennik")renderJournal();if(id==="cele")renderGoals();if(id==="plan")renderPlan();if(id==="zakupy")renderShopping()}
document.querySelectorAll("[data-go]").forEach(b=>b.onclick=()=>screen(b.dataset.go));
document.querySelectorAll(".back").forEach(b=>b.onclick=()=>screen("start"));

/* SKANER EAN + OPEN FOOD FACTS */
let eanScannerControls=null;
function stopEanScanner(){if(eanScannerControls){try{eanScannerControls.stop()}catch(e){}eanScannerControls=null}const v=$("eanScannerVideo");if(v?.srcObject){v.srcObject.getTracks().forEach(t=>t.stop());v.srcObject=null}$("eanScannerModal").classList.add("hide")}
async function lookupLocalEan(code){const value=String(code||"").replace(/\D/g,"");$("pe").value=value;const local=products.find(p=>String(p.ean||"")===value);if(local){stopEanScanner();editProduct(local.id);$("pmsg").textContent="Produkt o tym EAN jest już w Twojej bazie.";return true}return false}
async function productFromOpenFoodFacts(code){const fields="code,product_name,product_name_pl,brands,quantity,serving_size,image_front_small_url,nutriments,categories_tags";const url=`https://world.openfoodfacts.org/api/v2/product/${encodeURIComponent(code)}?fields=${fields}&lc=pl&cc=pl`;const r=await fetch(url);if(!r.ok)throw new Error("Open Food Facts: błąd połączenia "+r.status);const data=await r.json();return data?.product||null}
function offNumber(v){const n=Number(v);return Number.isFinite(n)?n:""}
function offKcal(n){if(Number.isFinite(Number(n?.["energy-kcal_100g"])))return Number(n["energy-kcal_100g"]);if(Number.isFinite(Number(n?.energy_100g)))return Number(n.energy_100g)/4.184;return""}
function offCategory(tags=[]){const t=(tags||[]).join(" ").toLowerCase();if(/vegetable|fruit|warzy|owoc/.test(t))return"Warzywa i owoce";if(/meat|fish|mięso|ryb/.test(t))return"Mięso i ryby";if(/dair|milk|cheese|yog|nabiał|ser/.test(t))return"Nabiał";if(/bread|bakery|pieczy/.test(t))return"Pieczywo";if(/pasta|rice|cereal|flour|makaron|ryż|mąk/.test(t))return"Produkty sypkie i makarony";if(/spice|sauce|condiment|przypraw|sos/.test(t))return"Przyprawy i dodatki";if(/frozen|mroż/.test(t))return"Mrożonki";if(/beverage|drink|napój/.test(t))return"Napoje";return"Inne"}
function parsePackGrams(product){const text=String(product?.quantity||product?.serving_size||"").replace(",",".");const m=text.match(/([0-9.]+)\s*(kg|g)\b/i);if(!m)return"";return Math.round(Number(m[1])*(m[2].toLowerCase()==="kg"?1000:1))}
function applyOffProduct(product){if(!product)return;const n=product.nutriments||{};$("pn").value=product.product_name_pl||product.product_name||"";$("pp").value=product.brands||"";$("pe").value=product.code||$("pe").value;const pack=parsePackGrams(product);if(pack!=="")$("po").value=pack;$("pk").value=offKcal(n);$("pb").value=offNumber(n.proteins_100g);$("pt").value=offNumber(n.fat_100g);$("pw").value=offNumber(n.carbohydrates_100g);$("pcat").value=offCategory(product.categories_tags);$("offResultsModal").classList.add("hide");$("pmsg").textContent="Dane pobrane z Open Food Facts. Sprawdź je z etykietą przed zapisaniem.";$("pn").focus()}
async function lookupEanInOff(code){$("eanScannerMsg").textContent="Szukam produktu w Open Food Facts...";try{const p=await productFromOpenFoodFacts(code);stopEanScanner();if(p){applyOffProduct(p)}else{$("pe").value=code;$("pmsg").textContent="EAN wpisany. Produktu nie znaleziono w Open Food Facts, uzupełnij dane ręcznie."}}catch(e){stopEanScanner();$("pe").value=code;$("pmsg").textContent=e.message}}
$("scanEan").onclick=async()=>{if(!window.ZXingBrowser){$("pmsg").textContent="Nie udało się załadować skanera. Sprawdź połączenie z Internetem.";return}$("eanScannerModal").classList.remove("hide");$("eanScannerMsg").textContent="Uruchamianie kamery...";try{const reader=new ZXingBrowser.BrowserMultiFormatReader();eanScannerControls=await reader.decodeFromConstraints({audio:false,video:{facingMode:{ideal:"environment"}}},$("eanScannerVideo"),(result,error,controls)=>{if(!result)return;const code=result.getText().replace(/\D/g,"");if(!/^\d{8,14}$/.test(code))return;controls.stop();eanScannerControls=null;lookupLocalEan(code).then(found=>{if(!found)lookupEanInOff(code)})});$("eanScannerMsg").textContent="Skaner działa. Ustaw kod w ramce kamery."}catch(e){stopEanScanner();$("pmsg").textContent="Nie udało się uruchomić kamery: "+e.message}};
$("stopEanScanner").onclick=stopEanScanner;$("closeEanScanner").onclick=stopEanScanner;
$("pe").addEventListener("change",async()=>{const code=$("pe").value.replace(/\D/g,"");if(!code)return;const found=await lookupLocalEan(code);if(!found)$("pmsg").textContent="EAN nie występuje jeszcze w Twojej bazie."});
async function searchOffByName(query){const q=String(query||"").trim();if(q.length<2){$("pmsg").textContent="Wpisz co najmniej 2 znaki nazwy produktu.";return}$("offResultsModal").classList.remove("hide");$("offResultsMsg").textContent="Wyszukiwanie...";$("offResults").innerHTML="";try{const params=new URLSearchParams({action:"process",json:"1",search_simple:"1",search_terms:q,page_size:"20",page:"1",fields:"code,product_name,product_name_pl,brands,quantity,serving_size,image_front_small_url,nutriments,categories_tags"});const r=await fetch("https://world.openfoodfacts.org/cgi/search.pl?"+params.toString());if(!r.ok)throw new Error("Open Food Facts: błąd wyszukiwania "+r.status);const data=await r.json();const rows=(data.products||[]).filter(p=>p.code&&(p.product_name||p.product_name_pl));$("offResultsMsg").textContent=rows.length?"Wybierz produkt i sprawdź dane przed zapisem.":"Nie znaleziono produktów.";$("offResults").innerHTML=rows.map((p,i)=>{const n=p.nutriments||{};return`<div class="offResult">${p.image_front_small_url?`<img src="${p.image_front_small_url}" alt="">`:'<div></div>'}<div><b>${p.product_name_pl||p.product_name}</b><small>${p.brands||"Brak producenta"} | EAN ${p.code}<br>${offKcal(n)===""?"Brak kcal":D2(offKcal(n))+" kcal/100 g"} | B  ${offNumber(n.proteins_100g)===""?"brak":D2(n.proteins_100g)+" g"} | T  ${offNumber(n.fat_100g)===""?"brak":D2(n.fat_100g)+" g"} | W  ${offNumber(n.carbohydrates_100g)===""?"brak":D2(n.carbohydrates_100g)+" g"}</small></div><button type="button" onclick="chooseOffResult(${i})">Wybierz</button></div>`}).join("");window.offSearchRows=rows}catch(e){$("offResultsMsg").textContent=e.message}};
window.chooseOffResult=i=>applyOffProduct(window.offSearchRows?.[i]);$("searchOpenFoodFacts").onclick=async()=>{const ean=String($("pe").value||"").replace(/\D/g,"");if(ean){const local=products.find(p=>String(p.ean||"")===ean);if(local){editProduct(local.id);$("pmsg").textContent="Produkt o tym EAN jest już w Twojej bazie.";return}$("pmsg").textContent="Szukam EAN w Open Food Facts...";try{const product=await productFromOpenFoodFacts(ean);if(product)applyOffProduct(product);else $("pmsg").textContent="Nie znaleziono tego EAN w Open Food Facts."}catch(e){$("pmsg").textContent=e.message}return}searchOffByName($("pn").value)};$("closeOffResults").onclick=()=>$("offResultsModal").classList.add("hide");

/* PRODUKTY */
function productRow(){return{nazwa:$("pn").value.trim(),producent:$("pp").value.trim()||null,ean:$("pe").value.trim()||null,opakowanie:N($("po").value),kcal:N($("pk").value),bialko:N($("pb").value),tluszcz:N($("pt").value),weglowodany:N($("pw").value),kategoria:$("pcat").value||"Inne"}}
function cancelProductEdit(){editProductId=null;$("productForm").reset();$("productSubmit").textContent="+ Dodaj produkt";$("productCancelEdit").classList.add("hide");$("pmsg").textContent=""}
function editProduct(id){const p=products.find(x=>x.id===id);if(!p)return;editProductId=id;$("pn").value=p.nazwa||"";$("pp").value=p.producent||"";$("pe").value=p.ean||"";$("po").value=p.opakowanie??"";$("pk").value=p.kcal??"";$("pb").value=p.bialko??"";$("pt").value=p.tluszcz??"";$("pw").value=p.weglowodany??"";$("pcat").value=p.kategoria||"Inne";$("productSubmit").textContent="Zapisz zmiany";$("productCancelEdit").classList.remove("hide");$("pmsg").textContent="Edycja: "+p.nazwa;$("pn").focus();window.scrollTo({top:0,behavior:"smooth"})}
$("productCancelEdit").onclick=cancelProductEdit;
function renderProductNameSuggest(){const box=$("productNameSuggest");if(!box)return;const q=norm($("pn").value);if(q.length<2){box.innerHTML="";box.classList.add("hide");return}const found=products.filter(p=>p.id!==editProductId&&norm(p.nazwa).includes(q)).slice(0,8);if(!found.length){box.innerHTML="";box.classList.add("hide");return}box.innerHTML=found.map(p=>`<div onclick="pickExistingProduct(${p.id})"><b>${p.nazwa}</b><small>${p.producent||""}</small></div>`).join("");box.classList.remove("hide")}
$("pn").addEventListener("input",renderProductNameSuggest);
window.pickExistingProduct=id=>{const p=products.find(x=>x.id===id);if(!p)return;$("productNameSuggest").classList.add("hide");editProduct(id)};
function resumeMealDraftIfNeeded(){const d=window.mealReturnDraft;if(!d)return;const name=d.newProductName;window.mealReturnDraft=null;screen("posilki");openMeal(d.editMeal?meals.find(x=>x.id===d.editMeal)||null:null);for(const [k,v] of Object.entries(d.fields))if($(k))$(k).value=v;setCategories(d.cats);temp=d.temp;const added=products.find(p=>norm(p.nazwa)===norm(name));if(added){chosenIng=added;$("isearch").value=added.nazwa}renderIng()}

$("productForm").onsubmit=async e=>{e.preventDefault();const row=productRow();if(!row.nazwa){$("pmsg").textContent="Podaj nazwę produktu";return}const r=editProductId?await supabaseClient.from("produkty").update(row).eq("id",editProductId):await supabaseClient.from("produkty").insert(row);$("pmsg").textContent=r.error?r.error.message:(editProductId?"Zapisano zmiany":"Zapisano produkt");if(!r.error){const savedName=row.nazwa,returnMeal=!!window.mealIngredientEditReturn;cancelProductEdit();await loadAll();if(returnMeal){resumeMealAfterIngredientProduct();return}if(jReturnContext?.type==="product"){resumeJournalAfterCreate(savedName,"product")}}};
function renderProducts(){const q=norm($("psearch").value);const visible=products.filter(p=>norm(p.nazwa+" "+(p.producent||"")+" "+(p.ean||"")).includes(q));$("plist").innerHTML=visible.map(p=>`<div class="item productItem"><div class="productPick" onclick="editProduct(${p.id})"><b>${p.nazwa}</b><small>${p.producent||""} | ${p.kategoria||"Inne"} | Porcja ${G(p.opakowanie)} g | ${D2(p.kcal)} kcal | B  ${D2(p.bialko)} T  ${D2(p.tluszcz)} W  ${D2(p.weglowodany)}</small></div><div><button onclick="editProduct(${p.id})">Edytuj</button><button class="danger" onclick="event.stopPropagation();delProduct(${p.id})">Usuń</button></div></div>`).join("")||"Brak produktów"}
$("psearch").oninput=renderProducts;window.editProduct=editProduct;
window.delProduct=async id=>{if(!confirm("Usunąć produkt?"))return;const r=await supabaseClient.from("produkty").delete().eq("id",id);if(r.error)alert(r.error.message);else{if(editProductId===id)cancelProductEdit();loadAll()}};

/* POSIŁKI */
const categoryInputs=()=>[...document.querySelectorAll('input[name="mealCategory"]')];
const selectedCategories=()=>categoryInputs().filter(x=>x.checked).map(x=>x.value);
function setCategories(values){const set=new Set(values||[]);categoryInputs().forEach(x=>x.checked=set.has(x.value))}
function categoriesOf(m){if(Array.isArray(m.kategorie)&&m.kategorie.length)return m.kategorie;return m.kategoria?[m.kategoria]:[]}
$("newMeal").onclick=()=>openMeal();$("cancelMeal").onclick=closeMealEditor;
function closeMealEditor(){$("mealEditor").classList.add("hide");$("mealNameSuggest").classList.add("hide");editMeal=null;if(planEditReturn){const r=planEditReturn;planEditReturn=null;screen("plan");$("planDate").value=r.date;loadPlan().then(()=>{if(r.entryId)setTimeout(()=>openPlanDetails(r.entryId),0)})}}
function openMeal(m=null){
 editMeal=m?.id||null;$("mealEditor").classList.remove("hide");$("mealEditorTitle").textContent=m?"Edycja posiłku":"Nowy przepis";$("saveMeal").textContent=m?"Zapisz zmiany":"Zapisz przepis";
 for(const id of["mn","mprep","mcook","mweight","minstr"])$(id).value="";$("mserv").value="1";$("mrating").value="0";setCategories([]);temp=[];
 if(m){$("mn").value=m.nazwa;$("mserv").value=m.liczba_porcji;$("mprep").value=m.czas_przygotowania;$("mcook").value=m.czas_gotowania;setCategories(categoriesOf(m));$("mrating").value=m.ocena;$("mweight").value=m.masa_gotowego_dania||"";$("minstr").value=m.instrukcja||"";temp=ingredients.filter(i=>i.posilek_id===m.id).map(i=>({...i,produkt:products.find(p=>p.id===i.produkt_id)})).filter(i=>i.produkt)}
 renderIng();$("mealNameSuggest").classList.add("hide");$("mn").focus();window.scrollTo({top:0,behavior:"smooth"});
}
$("mn").oninput=()=>{const q=norm($("mn").value);const box=$("mealNameSuggest");if(q.length<2){box.classList.add("hide");return}const found=meals.filter(m=>norm(m.nazwa).includes(q)).slice(0,8);if(!found.length){box.innerHTML="";box.classList.add("hide");return}box.innerHTML=found.map(m=>`<div onclick="openMealById(${m.id})"><b>${m.nazwa}</b><small>${categoriesOf(m).join(", ")||"Bez kategorii"}</small></div>`).join("");box.classList.remove("hide")};
window.openMealById=id=>{const m=meals.find(x=>x.id===id);if(m)openMeal(m)};
$("isearch").oninput=()=>{const raw=$("isearch").value.trim(),q=norm(raw),box=$("isuggest");box.className="suggest";if(!q){box.innerHTML="";return}const found=products.filter(p=>norm(p.nazwa).includes(q)).slice(0,8);box.innerHTML=found.map(p=>`<div onclick="pickIng(${p.id})">${p.nazwa}</div>`).join("")+(found.length?"":`<button type="button" class="addMissing" onclick="addProductFromMeal()">+ Dodaj nową żywność / produkt</button>`)};
window.addProductFromMeal=()=>{const name=$("isearch").value.trim();window.mealReturnDraft={editMeal,fields:{mn:$("mn").value,mserv:$("mserv").value,mprep:$("mprep").value,mcook:$("mcook").value,mrating:$("mrating").value,mweight:$("mweight").value,minstr:$("minstr").value},cats:selectedCategories(),temp:[...temp],newProductName:name};screen("produkty");$("pn").value=name;$("pn").focus()};
window.pickIng=id=>{chosenIng=products.find(p=>p.id===id);$("isearch").value=chosenIng.nazwa;$("isuggest").innerHTML=""};
$("iadd").onclick=e=>{e.preventDefault();const a=N($("iamount").value);if(!chosenIng||a<=0)return;temp.push({produkt_id:chosenIng.id,ilosc:a,produkt:chosenIng});chosenIng=null;$("isearch").value="";$("iamount").value="";renderIng()};
function totals(){return temp.reduce((s,i)=>({mass:s.mass+i.ilosc,k:s.k+N(i.produkt.kcal)*i.ilosc/100,b:s.b+N(i.produkt.bialko)*i.ilosc/100,t:s.t+N(i.produkt.tluszcz)*i.ilosc/100,w:s.w+N(i.produkt.weglowodany)*i.ilosc/100}),{mass:0,k:0,b:0,t:0,w:0})}
function renderIng(){const t=totals();$("ingredients").innerHTML=temp.map((i,n)=>{const p=i.produkt||{};return `<div class="item ingredientEditRow"><button type="button" class="ingredientProductPick" onclick="editIngredientProduct(${n})" title="Kliknij, aby edytować produkt">${p.producent?`<span class="ingredientManufacturer">${p.producent}</span>`:""}<b>${p.nazwa||"Produkt"}</b><small>${D2(p.kcal)} kcal/100 g | B  ${D2(p.bialko)} g | T  ${D2(p.tluszcz)} g | W  ${D2(p.weglowodany)} g</small></button><label>Ilość [g]<input type="number" min="0" step="1" value="${G(i.ilosc)}" onchange="editIngGram(${n},this.value)"></label><button class="danger" onclick="dropIng(${n})">Usuń</button></div>`}).join("");$("mealTotals").textContent=`Masa składników: ${G(t.mass)} g | ${D2(t.k)} kcal | B  ${D2(t.b)} g | T  ${D2(t.t)} g | W  ${D2(t.w)} g`}
window.editIngGram=(n,v)=>{if(!temp[n])return;temp[n].ilosc=Math.max(0,N(v));renderIng()};
window.dropIng=n=>{temp.splice(n,1);renderIng()};
window.editIngredientProduct=n=>{const item=temp[n];if(!item)return;window.mealIngredientEditReturn={index:n,editMeal,fields:{mn:$("mn").value,mserv:$("mserv").value,mprep:$("mprep").value,mcook:$("mcook").value,mrating:$("mrating").value,mweight:$("mweight").value,minstr:$("minstr").value},cats:selectedCategories(),temp:temp.map(x=>({...x,produkt:{...x.produkt}})),productId:item.produkt_id};screen("produkty");editProduct(item.produkt_id)};
function resumeMealAfterIngredientProduct(){const d=window.mealIngredientEditReturn;if(!d)return;window.mealIngredientEditReturn=null;screen("posilki");openMeal(d.editMeal?meals.find(x=>x.id===d.editMeal)||null:null);for(const [k,v] of Object.entries(d.fields))if($(k))$(k).value=v;setCategories(d.cats);temp=d.temp.map(x=>({...x,produkt:products.find(p=>p.id===x.produkt_id)||x.produkt}));renderIng()}
$("saveMeal").onclick=async()=>{const cats=selectedCategories();const row={nazwa:$("mn").value.trim(),liczba_porcji:N($("mserv").value),czas_przygotowania:N($("mprep").value),czas_gotowania:N($("mcook").value),kategoria:cats[0]||null,kategorie:cats,ocena:N($("mrating").value),masa_gotowego_dania:N($("mweight").value),instrukcja:$("minstr").value};if(!row.nazwa||!row.liczba_porcji||!temp.length||!cats.length){$("mmsg").textContent="Uzupełnij nazwę, porcje, przynajmniej jedną kategorię i składniki.";return}const result=editMeal?await supabaseClient.from("posilki").update(row).eq("id",editMeal).select().single():await supabaseClient.from("posilki").insert(row).select().single();if(result.error){$("mmsg").textContent=result.error.message;return}const id=result.data.id;await supabaseClient.from("skladniki_posilkow").delete().eq("posilek_id",id);const ins=await supabaseClient.from("skladniki_posilkow").insert(temp.map(i=>({posilek_id:id,produkt_id:i.produkt_id,ilosc:i.ilosc})));if(ins.error){$("mmsg").textContent=ins.error.message;return}const savedName=row.nazwa;closeMealEditor();await loadAll();if(jReturnContext?.type==="meal"){resumeJournalAfterCreate(savedName,"meal")}};
function mealMacro(m){const ls=ingredients.filter(i=>i.posilek_id===m.id),t=ls.reduce((s,i)=>{const p=products.find(x=>x.id===i.produkt_id)||{};return{k:s.k+N(p.kcal)*i.ilosc/100,b:s.b+N(p.bialko)*i.ilosc/100,t:s.t+N(p.tluszcz)*i.ilosc/100,w:s.w+N(p.weglowodany)*i.ilosc/100,mass:s.mass+N(i.ilosc)}},{k:0,b:0,t:0,w:0,mass:0}),n=N(m.liczba_porcji)||1;return{k:t.k/n,b:t.b/n,t:t.t/n,w:t.w/n,totalMass:t.mass,portionMass:(N(m.masa_gotowego_dania)>0?N(m.masa_gotowego_dania):t.mass)/n}}
function renderMeals(){const q=norm($("msearch").value);$("mealList").innerHTML=meals.filter(m=>norm(m.nazwa+" "+categoriesOf(m).join(" ")).includes(q)).map(m=>{const x=mealMacro(m);return`<div class="item mealItem"><div class="mealPick" onclick="openMealById(${m.id})"><b>${m.nazwa}</b><small>${categoriesOf(m).join(", ")||"Bez kategorii"} | 1 porcja (${D2(x.portionMass)} g) | ${D2(x.k)} kcal | ${"★".repeat(m.ocena||0)}${"☆".repeat(5-(m.ocena||0))}</small></div><div><button onclick="openMealById(${m.id})">Edytuj</button><button class="danger" onclick="event.stopPropagation();delM(${m.id})">Usuń</button></div></div>`}).join("")||"Brak posiłków"}
$("msearch").oninput=renderMeals;window.editM=id=>openMealById(id);window.delM=async id=>{if(!confirm("Usunąć posiłek?"))return;const r=await supabaseClient.from("posilki").delete().eq("id",id);if(r.error)alert(r.error.message);else loadAll()};

/* CELE */
function currentGoal(person){return goals.find(g=>g.osoba===person)||null}
function calculateGoalGrams(){const kcal=N($("goalCalories").value),c=N($("goalCarbsPercent").value),p=N($("goalProteinPercent").value),f=N($("goalFatPercent").value);$("goalCarbsGrams").textContent=D2(kcal*c/100/4)+" g";$("goalProteinGrams").textContent=D2(kcal*p/100/4)+" g";$("goalFatGrams").textContent=D2(kcal*f/100/9)+" g";const total=c+p+f;$("goalPercentSum").textContent="Suma: "+F(total)+"%";$("goalPercentSum").style.color=total===100?"#247a4b":"#a42e2e"}
function renderGoals(){if(!$("goalPerson"))return;const g=currentGoal($("goalPerson").value);$("goalCalories").value=g?.kalorie??"";$("goalCarbsPercent").value=g?.weglowodany_procent??"";$("goalProteinPercent").value=g?.bialko_procent??"";$("goalFatPercent").value=g?.tluszcz_procent??"";$("goalBreakfastPercent").value=g?.sniadanie_procent??30;$("goalLunchPercent").value=g?.obiad_procent??40;$("goalSnackPercent").value=g?.podwieczorek_procent??10;$("goalDinnerPercent").value=g?.kolacja_procent??20;$("goalCalcDate").textContent=g?.data_obliczenia?"Data ostatniego obliczenia: "+g.data_obliczenia:"Cel nie był jeszcze obliczany";$("calculateGoal").textContent=g?.data_obliczenia?"OBLICZ PONOWNIE GDA":"OBLICZ MÓJ CEL";$("goalMsg").textContent="";calculateGoalGrams();calculateMealSplit()}
$("goalPerson").onchange=renderGoals;["goalCalories","goalCarbsPercent","goalProteinPercent","goalFatPercent"].forEach(id=>$(id).oninput=calculateGoalGrams);["goalBreakfastPercent","goalLunchPercent","goalSnackPercent","goalDinnerPercent"].forEach(id=>$(id).oninput=calculateMealSplit);function calculateMealSplit(){const total=N($("goalBreakfastPercent").value)+N($("goalLunchPercent").value)+N($("goalSnackPercent").value)+N($("goalDinnerPercent").value);$("goalMealSum").textContent="Suma posiłków: "+F(total)+"%";$("goalMealSum").style.color=total===100?"#247a4b":"#a42e2e"}
$("saveGoals").onclick=async()=>{const kcal=N($("goalCalories").value),c=N($("goalCarbsPercent").value),p=N($("goalProteinPercent").value),f=N($("goalFatPercent").value);if(kcal<=0){$("goalMsg").textContent="Podaj cel kaloryczny większy od 0.";return}if(c+p+f!==100){$("goalMsg").textContent="Suma makroskładników musi wynosić dokładnie 100%.";return}const mealTotal=N($("goalBreakfastPercent").value)+N($("goalLunchPercent").value)+N($("goalSnackPercent").value)+N($("goalDinnerPercent").value);if(mealTotal!==100){$("goalMsg").textContent="Suma podziału kalorii na posiłki musi wynosić dokładnie 100%.";return}const row={osoba:$("goalPerson").value,kalorie:kcal,weglowodany_procent:c,bialko_procent:p,tluszcz_procent:f,weglowodany_gram:kcal*c/100/4,bialko_gram:kcal*p/100/4,tluszcz_gram:kcal*f/100/9,sniadanie_procent:N($("goalBreakfastPercent").value),drugie_sniadanie_procent:0,obiad_procent:N($("goalLunchPercent").value),podwieczorek_procent:N($("goalSnackPercent").value),kolacja_procent:N($("goalDinnerPercent").value)};const r=await supabaseClient.from("cele").upsert(row,{onConflict:"osoba"}).select().single();if(r.error){$("goalMsg").textContent=r.error.message;return}$("goalMsg").textContent="Cele zapisane.";await loadAll()};
$("calculateGoal").onclick=()=>{$("goalCalculatorModal").classList.remove("hide");$("calcResult").textContent="";$("calcMsg").textContent=""};$("closeGoalCalculator").onclick=()=>$("goalCalculatorModal").classList.add("hide");
function calculateGda(){const age=N($("calcAge").value),weight=N($("calcWeight").value),height=N($("calcHeight").value),activity=N($("calcActivity").value),adjustment=N($("calcAdjustment").value);if(age<=0||weight<=0||height<=0){$("calcMsg").textContent="Uzupełnij wiek, masę ciała i wzrost.";return null}const offset=$("calcVariant").value==="male"?5:-161,bmr=10*weight+6.25*height-5*age+offset,result=bmr*activity+adjustment;$("calcResult").textContent="Wyliczony cel: "+D2(result)+" kcal";$("calcMsg").textContent="";return result}
["calcVariant","calcAge","calcWeight","calcHeight","calcActivity","calcAdjustment"].forEach(id=>$(id).oninput=calculateGda);
$("applyCalculatedGoal").onclick=async()=>{const result=calculateGda();if(result===null)return;$("goalCalories").value=result;const today=new Date().toISOString().slice(0,10),person=$("goalPerson").value,c=N($("goalCarbsPercent").value),p=N($("goalProteinPercent").value),f=N($("goalFatPercent").value);const row={osoba:person,kalorie:result,weglowodany_procent:c,bialko_procent:p,tluszcz_procent:f,weglowodany_gram:result*c/100/4,bialko_gram:result*p/100/4,tluszcz_gram:result*f/100/9,data_obliczenia:today};const r=await supabaseClient.from("cele").upsert(row,{onConflict:"osoba"}).select().single();if(r.error){$("calcMsg").textContent=r.error.message;return}$("goalCalculatorModal").classList.add("hide");await loadAll()};

/* PLAN DIETY */
const planSlots=["Śniadanie","Obiad","Podwieczorek","Kolacja"];
const planPctField={"Śniadanie":"sniadanie_procent","Obiad":"obiad_procent","Podwieczorek":"podwieczorek_procent","Kolacja":"kolacja_procent"};
let planType="meal",planChosen=null,planSlot="";
function initPlanDate(){if($("planDate")&&!$("planDate").value)$("planDate").value=new Date().toISOString().slice(0,10)}
function planForDate(){return dietPlans.find(p=>p.data===$("planDate").value)||null}
function selectedPlanPeople(){const p=planForDate();if(!p)return[];return planUsersRows.filter(x=>x.plan_id===p.id).map(x=>x.osoba)}
function planGoal(person){return currentGoal(person)}
function sumSelectedGoals(people){return people.reduce((s,n)=>{const g=planGoal(n);if(!g)return s;s.k+=N(g.kalorie);s.b+=N(g.bialko_gram);s.t+=N(g.tluszcz_gram);s.w+=N(g.weglowodany_gram);return s},{k:0,b:0,t:0,w:0})}
function mealPct(goal,slot){return N(goal?.[planPctField[slot]])}
function plannedForPersonSlot(person,slot){const p=planForDate();if(!p)return{k:0,b:0,t:0,w:0};const ids=planEntries.filter(x=>x.plan_id===p.id&&x.rodzaj_posilku===slot).map(x=>x.id),portions=planPortions.filter(x=>ids.includes(x.pozycja_planu_id)&&x.osoba===person);return portions.reduce((s,x)=>({k:s.k+N(x.kcal),b:s.b+N(x.bialko),t:s.t+N(x.tluszcz),w:s.w+N(x.weglowodany)}),{k:0,b:0,t:0,w:0})}
async function ensurePlan(){initPlanDate();let p=planForDate();if(p)return p;const r=await supabaseClient.from("plan_diety").insert({data:$("planDate").value}).select().single();if(r.error)throw r.error;dietPlans.push(r.data);return r.data}
async function togglePlanUser(person,on){const g=planGoal(person);if(on&&!g){alert("Najpierw ustaw Cele dla użytkownika: "+person);renderPlan();return}const p=await ensurePlan();if(on){const r=await supabaseClient.from("plan_uczestnicy").upsert({plan_id:p.id,osoba:person},{onConflict:"plan_id,osoba"});if(r.error)alert(r.error.message)}else{await supabaseClient.from("plan_uczestnicy").delete().eq("plan_id",p.id).eq("osoba",person)}await loadAll()}
function renderPlan(){if(!$("planDate"))return;initPlanDate();const selected=selectedPlanPeople(),available=[...new Set(goals.filter(g=>N(g.kalorie)>0).map(g=>g.osoba))];$("planUsers").innerHTML=available.map(n=>`<label class="planUser"><input type="checkbox" ${selected.includes(n)?"checked":""} onchange="togglePlanUser('${n.replaceAll("'","\\'")}',this.checked)"> ${n}</label>`).join("")||"Brak użytkowników z ustawionymi Celami.";$("planUsersMsg").textContent=available.length?"Do wspólnego planu możesz zaznaczyć dowolną liczbę użytkowników z ustawionymi Celami.":"Najpierw ustaw Cel przynajmniej jednego użytkownika.";const target=sumSelectedGoals(selected);$("planTarget").innerHTML=`<div><small>Kalorie</small><b>${D2(target.k)} kcal</b></div><div><small>Białko</small><b>${D2(target.b)} g</b></div><div><small>Tłuszcz</small><b>${D2(target.t)} g</b></div><div><small>Węglowodany</small><b>${D2(target.w)} g</b></div>`;const p=planForDate();$("planMeals").innerHTML=planSlots.map(slot=>{const entriesFor=p?planEntries.filter(x=>x.plan_id===p.id&&x.rodzaj_posilku===slot):[];const peopleTargets=selected.map(person=>{const g=planGoal(person),pct=mealPct(g,slot)/100,used=plannedForPersonSlot(person,slot);return`<div class="planPersonTarget"><b>${person}</b>: cel ${D2(N(g.kalorie)*pct)} kcal | plan ${D2(used.k)} kcal | zostało ${D2(N(g.kalorie)*pct-used.k)} kcal</div>`}).join("");const rows=entriesFor.map(en=>{const name=en.produkt_id?(products.find(x=>x.id===en.produkt_id)?.nazwa||"Produkt"):(meals.find(x=>x.id===en.posilek_id)?.nazwa||"Posiłek");const pors=planPortions.filter(x=>x.pozycja_planu_id===en.id).map(x=>`${x.osoba}: ${G(x.gramy)} g (${D2(x.kcal)} kcal)`).join(" | ");return`<div class="planEntry"><div class="planEntryTop"><b onclick="openPlanDetails(${en.id})">${name}</b><div><button onclick="openPlanDetails(${en.id})">Podgląd</button><button class="danger" onclick="deletePlanEntry(${en.id})">Usuń</button></div></div><small>${pors}</small></div>`}).join("");return`<section class="planMealBox"><div class="planMealHeader"><h2>${slot}</h2><button class="primary" onclick="openPlanModal('${slot}')">＋ Dodaj pozycję</button></div>${peopleTargets}${rows}</section>`}).join("")}
window.togglePlanUser=togglePlanUser;$("planDate").onchange=renderPlan;
window.openPlanModal=slot=>{const people=selectedPlanPeople();if(!people.length){alert("Najpierw zaznacz użytkowników planu.");return}planSlot=slot;planType="meal";planChosen=null;$("planModal").classList.remove("hide");$("planMealName").textContent=slot;$("planSearch").value="";$("planResults").innerHTML="";$("planChosen").classList.add("hide");$("planPortions").innerHTML="";$("planPreview").textContent="";planTabs()};
function planTabs(){$("planTabProduct").classList.toggle("active",planType==="product");$("planTabMeal").classList.toggle("active",planType==="meal")}
$("planTabProduct").onclick=()=>{planType="product";planChosen=null;planTabs();renderPlanSearch()};$("planTabMeal").onclick=()=>{planType="meal";planChosen=null;planTabs();renderPlanSearch()};$("planSearch").oninput=renderPlanSearch;
function renderPlanSearch(){const q=norm($("planSearch").value),a=planType==="product"?products:meals;$("planResults").innerHTML=a.filter(x=>norm(x.nazwa).includes(q)).slice(0,12).map(x=>`<div onclick="choosePlanItem(${x.id})"><b>${x.nazwa}</b></div>`).join("")}
function itemPerGram(){if(!planChosen)return{k:0,b:0,t:0,w:0};if(planType==="product")return{k:N(planChosen.kcal)/100,b:N(planChosen.bialko)/100,t:N(planChosen.tluszcz)/100,w:N(planChosen.weglowodany)/100};const mm=mealMacro(planChosen),mass=N(planChosen.masa_gotowego_dania)>0?N(planChosen.masa_gotowego_dania):mm.totalMass;return mass>0?{k:mm.k*(N(planChosen.liczba_porcji)||1)/mass,b:mm.b*(N(planChosen.liczba_porcji)||1)/mass,t:mm.t*(N(planChosen.liczba_porcji)||1)/mass,w:mm.w*(N(planChosen.liczba_porcji)||1)/mass}:{k:0,b:0,t:0,w:0}}
window.choosePlanItem=id=>{planChosen=(planType==="product"?products:meals).find(x=>x.id===id);$("planChosen").textContent=planChosen.nazwa;$("planChosen").classList.remove("hide");const pg=itemPerGram(),people=selectedPlanPeople();if(planType==="meal"){const mm=mealMacro(planChosen),originalMass=N(planChosen.masa_gotowego_dania)>0?N(planChosen.masa_gotowego_dania):mm.totalMass;const weights=people.map(person=>{const g=planGoal(person),target=N(g.kalorie)*mealPct(g,planSlot)/100,used=plannedForPersonSlot(person,planSlot);return Math.max(0,target-used.k)}),sumW=weights.reduce((a,b)=>a+b,0);$("planPortions").innerHTML=people.map((person,i)=>{const suggested=people.length===1?originalMass:(sumW>0?originalMass*weights[i]/sumW:originalMass/people.length);return `<div class="planPortionRow"><b>${person}</b><input class="planGramInput" data-person="${person}" type="number" step="1" min="0" value="${G(suggested)}"><small class="planSuggestion">Oryginalny przepis: razem ${G(originalMass)} g. Zmieniasz podział gotowego dania między osoby, nie proporcje składników.</small></div>`}).join("")}else{$("planPortions").innerHTML=people.map(person=>{const g=planGoal(person),target=N(g.kalorie)*mealPct(g,planSlot)/100,used=plannedForPersonSlot(person,planSlot),remaining=Math.max(0,target-used.k),suggested=pg.k>0?remaining/pg.k:0;return `<div class="planPortionRow"><b>${person}</b><input class="planGramInput" data-person="${person}" type="number" step="1" min="0" value="${G(suggested)}"><small class="planSuggestion">Podpowiedź: ${G(suggested)} g, aby zbliżyć ${planSlot.toLowerCase()} do celu kcal.</small></div>`}).join("")}document.querySelectorAll(".planGramInput").forEach(x=>x.oninput=previewPlanItem);previewPlanItem()};
function previewPlanItem(){const pg=itemPerGram();let t={k:0,b:0,t:0,w:0};document.querySelectorAll(".planGramInput").forEach(x=>{const g=N(x.value);t.k+=pg.k*g;t.b+=pg.b*g;t.t+=pg.t*g;t.w+=pg.w*g});$("planPreview").textContent=`Razem: ${D2(t.k)} kcal | B  ${D2(t.b)} g | T  ${D2(t.t)} g | W  ${D2(t.w)} g`;return t}
$("planSave").onclick=async()=>{if(!planChosen)return;const p=await ensurePlan(),entry={plan_id:p.id,rodzaj_posilku:planSlot,produkt_id:planType==="product"?planChosen.id:null,posilek_id:planType==="meal"?planChosen.id:null},er=await supabaseClient.from("pozycje_planu").insert(entry).select().single();if(er.error){$("planMsg").textContent=er.error.message;return}const pg=itemPerGram(),rows=[...document.querySelectorAll(".planGramInput")].filter(x=>N(x.value)>0).map(x=>{const g=N(x.value);return{pozycja_planu_id:er.data.id,osoba:x.dataset.person,gramy:g,kcal:pg.k*g,bialko:pg.b*g,tluszcz:pg.t*g,weglowodany:pg.w*g}});if(rows.length){const r=await supabaseClient.from("porcje_planu").insert(rows);if(r.error){$("planMsg").textContent=r.error.message;return}}$("planModal").classList.add("hide");await loadAll()};
let detailPlanEntry=null;let planEditReturn=null;
window.openPlanDetails=id=>{const en=planEntries.find(x=>x.id===id);if(!en)return;detailPlanEntry=en;const meal=en.posilek_id?meals.find(x=>x.id===en.posilek_id):null,product=en.produkt_id?products.find(x=>x.id===en.produkt_id):null;const portions=planPortions.filter(x=>x.pozycja_planu_id===id);$("planDetailsModal").classList.remove("hide");$("planDetailsTitle").textContent=meal?meal.nazwa:(product?.nazwa||"Szczegóły pozycji");if(meal){const baseIngredients=ingredients.filter(i=>i.posilek_id===meal.id);const mm=mealMacro(meal);const originalMass=N(meal.masa_gotowego_dania)>0?N(meal.masa_gotowego_dania):mm.totalMass;const plannedMass=portions.reduce((s,p)=>s+N(p.gramy),0);$("planDetailsIngredients").innerHTML=baseIngredients.map(i=>{const p=products.find(x=>x.id===i.produkt_id);return`<div class="planIngredient"><span>${p?.nazwa||"Produkt"}</span><b>${G(i.ilosc)} g</b></div>`}).join("");const recipe=baseIngredients.reduce((s,i)=>{const p=products.find(x=>x.id===i.produkt_id)||{};return{k:s.k+N(p.kcal)*N(i.ilosc)/100,b:s.b+N(p.bialko)*N(i.ilosc)/100,t:s.t+N(p.tluszcz)*N(i.ilosc)/100,w:s.w+N(p.weglowodany)*N(i.ilosc)/100}},{k:0,b:0,t:0,w:0});$("planDetailsTotals").textContent=`Oryginalny przepis: ${G(originalMass)} g | ${D2(recipe.k)} kcal | B  ${D2(recipe.b)} g | T  ${D2(recipe.t)} g | W  ${D2(recipe.w)} g`;$("planCookedMass").value=G(originalMass||plannedMass);$("planDetailsInstructions").textContent=meal.instrukcja||"Brak instrukcji.";$("planDetailsEditRecipe").classList.remove("hide");$("planDetailsEditRecipe").onclick=()=>{planEditReturn={date:$("planDate").value,entryId:en.id};$("planDetailsModal").classList.add("hide");screen("posilki");openMeal(meal)};const plan=planForDate();const people=planUsersRows.filter(x=>x.plan_id===plan?.id).map(x=>x.osoba);$("planDetailsTargets").innerHTML=people.map(person=>{const g=planGoal(person),pct=mealPct(g,en.rodzaj_posilku)/100;return`<span>${person}: cel ${D2(N(g?.kalorie)*pct)} kcal</span>`}).join(" | ");renderCookedSplit()}else{$("planDetailsIngredients").innerHTML=`<div class="planIngredient"><span>${product?.nazwa||"Produkt"}</span><b>${G(portions.reduce((s,p)=>s+N(p.gramy),0))} g</b></div>`;$("planDetailsTotals").textContent=portions.length?`${D2(portions.reduce((s,p)=>s+N(p.kcal),0))} kcal`:"";$("planCookedMass").value="";$("planCookedMass").disabled=true;$("planDetailsPortions").innerHTML=portions.map(p=>`<div class="planDetailsPortion"><span>${p.osoba}</span><b>${G(p.gramy)} g</b></div>`).join("");$("planDetailsInstructions").textContent="Pozycja jest pojedynczym produktem.";$("planDetailsEditRecipe").classList.add("hide");$("planDetailsTargets").textContent=""}}
function renderCookedSplit(){if(!detailPlanEntry?.posilek_id)return;$("planCookedMass").disabled=false;const portions=planPortions.filter(x=>x.pozycja_planu_id===detailPlanEntry.id),planned=portions.reduce((s,p)=>s+N(p.gramy),0),cooked=N($("planCookedMass").value);$("planDetailsPortions").innerHTML=portions.map(p=>{const grams=planned>0?cooked*N(p.gramy)/planned:0;return`<div class="planDetailsPortion"><span>${p.osoba}</span><b>${G(grams)} g</b></div>`}).join("")}
$("planCookedMass").oninput=renderCookedSplit;$("planDetailsClose").onclick=()=>{$("planDetailsModal").classList.add("hide");detailPlanEntry=null};
window.deletePlanEntry=async id=>{if(!confirm("Usunąć pozycję z planu?"))return;await supabaseClient.from("pozycje_planu").delete().eq("id",id);await loadAll()};$("planClose").onclick=()=>$("planModal").classList.add("hide");

/* DZIENNIK */
const slots=["Śniadanie","Obiad","Podwieczorek","Kolacja"],slug=s=>norm(s).replaceAll(" ","-");
function initDate(){if(!$("jdate").value)$("jdate").value=new Date().toISOString().slice(0,10)}
function dayRows(){const ids=journal.filter(x=>x.osoba===$("jperson").value&&x.data===$("jdate").value).map(x=>x.id);return entries.filter(e=>ids.includes(e.dziennik_id))}
function renderJournal(){initDate();const diaryGoal=currentGoal($("jperson").value),diaryRows=dayRows();$("journalMeals").innerHTML=slots.map(slot=>{const target=diaryGoal?N(diaryGoal.kalorie)*mealPct(diaryGoal,slot)/100:0,used=diaryRows.filter(e=>journal.find(d=>d.id===e.dziennik_id)?.rodzaj_posilku===slot).reduce((a,e)=>a+N(e.kcal),0),left=target-used;return `<section class="journalBox"><div class="journalHeading"><h2>${slot}</h2><div class="mealKcalTarget">${diaryGoal?`Cel ${D2(target)} kcal | Spożyto ${D2(used)} kcal | Zostało ${D2(left)} kcal`:"Brak celu kcal"}</div></div><div id="jr-${slug(slot)}"></div><button class="addJournal" onclick="openJ('${slot}')">＋ Dodaj pozycję</button></section>`}).join("");const list=diaryRows,sum={k:0,b:0,t:0,w:0};for(const e of list){sum.k+=N(e.kcal);sum.b+=N(e.bialko);sum.t+=N(e.tluszcz);sum.w+=N(e.weglowodany);const d=journal.find(x=>x.id===e.dziennik_id),name=e.produkt_id?(products.find(x=>x.id===e.produkt_id)?.nazwa||"Produkt"):(meals.find(x=>x.id===e.posilek_id)?.nazwa||"Posiłek"),opis=e.produkt_id?G(e.ilosc_gram)+" g":(()=>{const m=meals.find(x=>x.id===e.posilek_id),mm=m?mealMacro(m):null,serv=Math.max(1,N(m?.liczba_porcji)||1),grams=mm?(N(m?.masa_gotowego_dania)>0?N(m.masa_gotowego_dania):mm.totalMass)*N(e.liczba_porcji)/serv:0;return F(e.liczba_porcji)+" porcji ("+G(grams)+" g)"})();$("jr-"+slug(d.rodzaj_posilku)).innerHTML+=`<div class="journalRow"><div><b>${name}</b><small>${opis}</small></div><span class="macro">${D2(e.kcal)} kcal</span><span class="macro">B  ${D2(e.bialko)}</span><span class="macro">T  ${D2(e.tluszcz)}</span><span class="macro">W  ${D2(e.weglowodany)}</span><div class="journalActions"><button onclick="editJ(${e.id})">Edytuj</button><button class="danger" onclick="delJ(${e.id})">Usuń</button></div></div>`}const goal=currentGoal($("jperson").value);$("jk").textContent=D2(sum.k)+" kcal";$("jb").textContent="B "+D2(sum.b)+" g";$("jt").textContent="T "+D2(sum.t)+" g";$("jw").textContent="W "+D2(sum.w)+" g";$("jGoalCalories").textContent=goal?D2(goal.kalorie)+" kcal":"Brak celu";$("jRemainingCalories").textContent=goal?D2(goal.kalorie-sum.k)+" kcal":"Brak celu";$("jbGoal").textContent=goal?"/ "+D2(goal.bialko_gram)+" g":"/ brak celu";$("jtGoal").textContent=goal?"/ "+D2(goal.tluszcz_gram)+" g":"/ brak celu";$("jwGoal").textContent=goal?"/ "+D2(goal.weglowodany_gram)+" g":"/ brak celu"}
function resetJournalModal(){editJournalId=null;jChosen=null;$("jsearch").value="";$("jresults").innerHTML="";$("jchosen").classList.add("hide");$("jamount").value="";$("jadd").textContent="Dodaj do dziennika";$("jcancelEdit").classList.add("hide");$("jmsg").textContent=""}
function offProductRow(product){const n=product?.nutriments||{};return{nazwa:product?.product_name_pl||product?.product_name||"Produkt EAN",producent:product?.brands||null,ean:String(product?.code||""),opakowanie:parsePackGrams(product)||0,kcal:N(offKcal(n)),bialko:N(offNumber(n.proteins_100g)),tluszcz:N(offNumber(n.fat_100g)),weglowodany:N(offNumber(n.carbohydrates_100g)),kategoria:offCategory(product?.categories_tags)}}
function selectJournalProduct(product){jType="product";jChosen=product;$("jchosen").textContent=product.nazwa;$("jchosen").classList.remove("hide");$("jsearch").value=product.nazwa;tab();preview();$("jmsg").textContent="Produkt wybrany ze skanera. Wpisz zjedzoną ilość w gramach."}
async function handleJournalScannedEan(code){const value=String(code||"").replace(/\D/g,"");const local=products.find(p=>String(p.ean||"")===value);if(local){stopEanScanner();selectJournalProduct(local);return}$("eanScannerMsg").textContent="Szukam produktu w Open Food Facts...";try{const product=await productFromOpenFoodFacts(value);stopEanScanner();if(!product){jReturnContext=journalContext();$("journalModal").classList.add("hide");screen("produkty");cancelProductEdit();$("pe").value=value;$("pmsg").textContent="Produktu nie znaleziono. Uzupełnij dane i zapisz, aby wrócić do Dziennika.";return}const row=offProductRow(product);const summary=`${row.nazwa}\n${row.producent||"Brak producenta"}\nEAN: ${value}\n${D2(row.kcal)} kcal/100 g | B  ${D2(row.bialko)} g | T  ${D2(row.tluszcz)} g | W  ${D2(row.weglowodany)} g\n\nDodać produkt do Twojej bazy i wybrać go w Dzienniku?`;if(!confirm(summary)){jReturnContext=journalContext();$("journalModal").classList.add("hide");screen("produkty");cancelProductEdit();applyOffProduct(product);$("pmsg").textContent="Sprawdź dane z etykietą, zapisz produkt i wróć do rozpoczętego wpisu Dziennika.";return}const r=await supabaseClient.from("produkty").insert(row).select().single();if(r.error){$("jmsg").textContent="Nie udało się dodać produktu: "+r.error.message;return}products.push(r.data);renderProducts();selectJournalProduct(r.data)}catch(e){stopEanScanner();$("jmsg").textContent=e.message}}
async function startJournalScanner(){if(!window.ZXingBrowser){$("jmsg").textContent="Nie udało się załadować skanera. Sprawdź połączenie z Internetem.";return}jType="product";tab();$("eanScannerModal").classList.remove("hide");$("eanScannerMsg").textContent="Uruchamianie kamery...";try{const reader=new ZXingBrowser.BrowserMultiFormatReader();eanScannerControls=await reader.decodeFromConstraints({audio:false,video:{facingMode:{ideal:"environment"}}},$("eanScannerVideo"),(result,error,controls)=>{if(!result)return;const code=result.getText().replace(/\D/g,"");if(!/^\d{8,14}$/.test(code))return;controls.stop();eanScannerControls=null;handleJournalScannedEan(code)});$("eanScannerMsg").textContent="Skaner działa. Ustaw kod w ramce kamery."}catch(e){stopEanScanner();$("jmsg").textContent="Nie udało się uruchomić kamery: "+e.message}}
$("tabScan").onclick=startJournalScanner;

window.openJ=s=>{jSlot=s;jType="product";resetJournalModal();$("journalModal").classList.remove("hide");$("jmealName").textContent=s;tab();preview();renderJournalSearch()};
function tab(){$("tabProduct").classList.toggle("active",jType==="product");$("tabMeal").classList.toggle("active",jType==="meal");$("tabScan").classList.remove("active");$("jamountLabel").childNodes[0].nodeValue=jType==="product"?"Ilość [g]":"Liczba porcji";$("jportionMass").classList.toggle("hide",jType!=="meal");$("jcreateNew").textContent=jType==="product"?"＋ Dodaj nową żywność / produkt":"＋ Dodaj nowy posiłek"}
$("tabProduct").onclick=()=>{jType="product";jChosen=null;$("jchosen").classList.add("hide");tab();preview();renderJournalSearch()};
$("tabMeal").onclick=()=>{jType="meal";jChosen=null;$("jchosen").classList.add("hide");tab();preview();renderJournalSearch()};
function renderJournalSearch(){const q=norm($("jsearch").value),a=jType==="product"?products:meals;$("jresults").innerHTML=a.filter(x=>norm(x.nazwa).includes(q)).slice(0,10).map(x=>`<div onclick="chooseJ(${x.id})"><b>${x.nazwa}</b></div>`).join("")}
$("jsearch").oninput=renderJournalSearch;
window.chooseJ=id=>{jChosen=(jType==="product"?products:meals).find(x=>x.id===id);$("jchosen").textContent=jChosen.nazwa;$("jchosen").classList.remove("hide");preview()};
$("jamount").oninput=preview;
function preview(){if(!jChosen){$("jpreview").textContent="";$("jportionMass").textContent="";return null}const a=N($("jamount").value);let v;if(jType==="product"){v={k:jChosen.kcal*a/100,b:jChosen.bialko*a/100,t:jChosen.tluszcz*a/100,w:jChosen.weglowodany*a/100,mass:a}}else{const x=mealMacro(jChosen);v={k:x.k*a,b:x.b*a,t:x.t*a,w:x.w*a,mass:x.portionMass*a};$("jportionMass").textContent=F(a)+" porcji ("+F(v.mass)+" g)";$("jportionMass").classList.remove("hide")}$("jpreview").textContent=`${D2(v.k)} kcal | B  ${D2(v.b)} g | T  ${D2(v.t)} g | W  ${D2(v.w)} g`;return v}
function journalContext(){return{slot:jSlot,person:$("jperson").value,date:$("jdate").value,query:$("jsearch").value,type:jType}}
$("jcreateNew").onclick=()=>{jReturnContext=journalContext();$("journalModal").classList.add("hide");if(jType==="product"){screen("produkty");cancelProductEdit();$("pn").value=jReturnContext.query;$("pn").focus()}else{screen("posilki");openMeal();$("mn").value=jReturnContext.query;$("mn").focus()}};
function resumeJournalAfterCreate(name,type){const ctx=jReturnContext;jReturnContext=null;if(!ctx)return;$("jperson").value=ctx.person;$("jdate").value=ctx.date;screen("dziennik");jSlot=ctx.slot;jType=type;resetJournalModal();$("journalModal").classList.remove("hide");$("jmealName").textContent=ctx.slot;tab();const source=type==="product"?products:meals;jChosen=source.find(x=>norm(x.nazwa)===norm(name))||null;if(jChosen){$("jchosen").textContent=jChosen.nazwa;$("jchosen").classList.remove("hide")}preview()}
window.editJ=id=>{const e=entries.find(x=>x.id===id);if(!e)return;const d=journal.find(x=>x.id===e.dziennik_id);if(!d)return;editJournalId=id;jSlot=d.rodzaj_posilku;jType=e.produkt_id?"product":"meal";jChosen=jType==="product"?products.find(x=>x.id===e.produkt_id):meals.find(x=>x.id===e.posilek_id);$("journalModal").classList.remove("hide");$("jmealName").textContent=jSlot;$("jsearch").value=jChosen?.nazwa||"";$("jchosen").textContent=jChosen?.nazwa||"";$("jchosen").classList.toggle("hide",!jChosen);$("jamount").value=jType==="product"?e.ilosc_gram:e.liczba_porcji;$("jadd").textContent="Zapisz zmiany";$("jcancelEdit").classList.remove("hide");$("jmsg").textContent="Edycja pozycji";tab();renderJournalSearch();preview()};
$("jcancelEdit").onclick=()=>{$("journalModal").classList.add("hide");resetJournalModal()};
$("jadd").onclick=async()=>{const a=N($("jamount").value),v=preview();if(!jChosen||a<=0||!v)return;let d=journal.find(x=>x.osoba===$("jperson").value&&x.data===$("jdate").value&&x.rodzaj_posilku===jSlot);if(!d){const r=await supabaseClient.from("dziennik").insert({osoba:$("jperson").value,data:$("jdate").value,rodzaj_posilku:jSlot}).select().single();if(r.error){$("jmsg").textContent=r.error.message;return}d=r.data}const row={dziennik_id:d.id,produkt_id:jType==="product"?jChosen.id:null,posilek_id:jType==="meal"?jChosen.id:null,ilosc_gram:jType==="product"?a:v.mass,liczba_porcji:jType==="meal"?a:null,kcal:v.k,bialko:v.b,tluszcz:v.t,weglowodany:v.w};const r=editJournalId?await supabaseClient.from("pozycje_dziennika").update(row).eq("id",editJournalId):await supabaseClient.from("pozycje_dziennika").insert(row);if(r.error){$("jmsg").textContent=r.error.message;return}$("journalModal").classList.add("hide");resetJournalModal();await loadAll()};
window.delJ=async id=>{if(!confirm("Usunąć pozycję z Dziennika?"))return;await supabaseClient.from("pozycje_dziennika").delete().eq("id",id);loadAll()};
$("jclose").onclick=()=>{$("journalModal").classList.add("hide");resetJournalModal()};$("jperson").onchange=renderJournal;$("jdate").onchange=renderJournal;
/* LISTA ZAKUPÓW */
const shoppingCategories=["Warzywa i owoce","Mięso i ryby","Nabiał","Pieczywo","Produkty sypkie i makarony","Przyprawy i dodatki","Konserwy i produkty gotowe","Mrożonki","Napoje","Inne"];
function initShoppingDates(){if(!$("shoppingFrom"))return;const today=new Date().toISOString().slice(0,10);if(!$("shoppingFrom").value)$("shoppingFrom").value=today;if(!$("shoppingTo").value)$("shoppingTo").value=$("shoppingFrom").value}
function shoppingNeeded(){initShoppingDates();const from=$("shoppingFrom").value,to=$("shoppingTo").value,plans=dietPlans.filter(p=>p.data>=from&&p.data<=to),planIds=plans.map(p=>p.id),ens=planEntries.filter(e=>planIds.includes(e.plan_id)),result=new Map();function add(pid,grams){const p=products.find(x=>x.id===pid);if(!p||grams<=0)return;const old=result.get(pid)||{product:p,grams:0};old.grams+=grams;result.set(pid,old)}for(const en of ens){const portions=planPortions.filter(x=>x.pozycja_planu_id===en.id),plannedMass=portions.reduce((s,x)=>s+N(x.gramy),0);if(en.produkt_id){add(en.produkt_id,plannedMass);continue}const meal=meals.find(x=>x.id===en.posilek_id);if(!meal)continue;const base=ingredients.filter(i=>i.posilek_id===meal.id),mm=mealMacro(meal),baseMass=N(meal.masa_gotowego_dania)>0?N(meal.masa_gotowego_dania):mm.totalMass,factor=baseMass>0?plannedMass/baseMass:0;base.forEach(i=>add(i.produkt_id,N(i.ilosc)*factor))}return [...result.values()]}
function priceRow(pid){return shoppingPrices.find(x=>x.produkt_id===pid)||null}
function renderShopping(){if(!$("shoppingList"))return;initShoppingDates();const items=shoppingNeeded();let total=0;$("shoppingList").innerHTML=shoppingCategories.map(cat=>{const list=items.filter(x=>(x.product.kategoria||"Inne")===cat);if(!list.length)return"";return`<div class="shoppingCategory"><h3>${cat}</h3>${list.map(x=>{const p=x.product,pr=priceRow(p.id),pack=N(pr?.gramy_opakowania)||N(p.opakowanie),count=pack>0?Math.ceil(x.grams/pack):0,pricePack=N(pr?.cena_opakowania),priceKg=N(pr?.cena_kg),cost=count*pricePack;total+=cost;return`<div class="shoppingRow" data-product="${p.id}"><div class="shoppingName"><strong>${p.nazwa}</strong><small>Potrzeba: ${G(x.grams)} g${pack>0?` | ${count} op. × ${G(pack)} g`:""}</small></div><label>Status<select class="shopStatus"><option ${pr?.status==="KUPIĆ"?"selected":""}>KUPIĆ</option><option ${pr?.status==="MAMY"?"selected":""}>MAMY</option><option ${pr?.status==="KUPIONE"?"selected":""}>KUPIONE</option></select></label><label>Opakowanie [g]<input class="shopPack" type="number" step="1" min="0" value="${pack||""}"></label><label>Cena opak. [zł]<input class="shopPricePack" type="number" step="0.01" min="0" value="${pricePack||""}"></label><label>Cena [zł/kg]<input class="shopPriceKg" type="number" step="0.01" min="0" value="${priceKg||""}"></label><div class="shoppingCost">${cost?D2(cost)+" zł":"Brak ceny"}</div><button onclick="saveShopPrice(${p.id},'pack')">Zapisz</button></div>`}).join("")}</div>`}).join("")||"Brak produktów wynikających z Planu diety w wybranym okresie.";$("shoppingSummary").textContent=`Szacowany koszt zakupów: ${D2(total)} zł`;wireShoppingInputs()}
function wireShoppingInputs(){document.querySelectorAll(".shoppingRow").forEach(row=>{const pack=row.querySelector(".shopPack"),pp=row.querySelector(".shopPricePack"),pk=row.querySelector(".shopPriceKg");pp.oninput=()=>{const g=N(pack.value),v=N(pp.value);if(g>0)pk.value=(v/g*1000).toFixed(2)};pk.oninput=()=>{const g=N(pack.value),v=N(pk.value);if(g>0)pp.value=(v*g/1000).toFixed(2)};pack.oninput=()=>{const g=N(pack.value),v=N(pk.value);if(g>0&&v>0)pp.value=(v*g/1000).toFixed(2)}})}
window.saveShopPrice=async pid=>{const row=document.querySelector(`.shoppingRow[data-product="${pid}"]`),data={produkt_id:pid,gramy_opakowania:N(row.querySelector(".shopPack").value),cena_opakowania:N(row.querySelector(".shopPricePack").value),cena_kg:N(row.querySelector(".shopPriceKg").value),status:row.querySelector(".shopStatus").value};const r=await supabaseClient.from("ceny_zakupow").upsert(data,{onConflict:"produkt_id"});if(r.error){$("shoppingMsg").textContent=r.error.message;return}$("shoppingMsg").textContent="Zapisano cenę i status.";await loadAll()};
$("refreshShopping").onclick=renderShopping;$("shoppingFrom").onchange=renderShopping;$("shoppingTo").onchange=renderShopping;

